import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

/**
 * Applies committed migrations from `drizzle/` (generated by `bun run db:generate`). Idempotent;
 * used at server start and by the test setup. Uses its own single connection, closed afterwards.
 */
export async function runMigrations(url: string, migrationsFolder = "drizzle"): Promise<void> {
  const client = postgres(url, { max: 1, onnotice: () => {} });
  try {
    await migrate(drizzle({ client }), { migrationsFolder });
  } finally {
    await client.end();
  }
}
